const fmtDate = (d) => {
  if (!d || d.length !== 8) return d || "";
  return d.slice(0, 4) + "-" + d.slice(4, 6) + "-" + d.slice(6, 8);
};

return items.map((item) => {
  const j = item.json;
  const er = j.engagementRate !== undefined && j.engagementRate !== "" ? Number((Number(j.engagementRate) * 100).toFixed(2)) : "";
  return {
    json: {
      "Date": fmtDate(j.date),
      "Sessions": j.sessions !== undefined ? Number(j.sessions) : "",
      "Total Users": j.totalUsers !== undefined ? Number(j.totalUsers) : "",
      "New Users": j.newUsers !== undefined ? Number(j.newUsers) : "",
      "Screen Page Views": j.screenPageViews !== undefined ? Number(j.screenPageViews) : "",
      "Engagement Rate (%)": er
    }
  };
});

// Create one XLSX file with 4 worksheets:
// 1. GA4 Summary
// 2. GA4 Page Performance
// 3. GSC Queries
// 4. GSC Pages
//
// Important:
// This code does NOT use the final merge rows for report data.
// It directly reads the 4 report nodes.

function getNodeRows(nodeName) {
  try {
    return $items(nodeName).map(item => item.json || {});
  } catch (error) {
    return [];
  }
}

const ga4SummaryItemsRaw = getNodeRows("Generate GA4 Report");
const ga4PagePerformanceItemsRaw = getNodeRows("Generate GA4 Page Performance Report");
const gscQueryItemsRaw = getNodeRows("Generate SEO Report");
const gscPageItemsRaw = getNodeRows("Generate GSC Page Report Data");

const fileName = `Weekly_SEO_GA4_Report_${$now.toFormat("yyyy-MM-dd")}.xlsx`;

function cleanRows(rows, allowedHeaders) {
  return rows.map(row => {
    const cleaned = {};

    for (const header of allowedHeaders) {
      cleaned[header] = row[header] !== undefined && row[header] !== null ? row[header] : "";
    }

    return cleaned;
  });
}

const ga4SummaryHeaders = [
  "Date",
  "Sessions",
  "Total Users",
  "New Users",
  "Screen Page Views",
  "Engagement Rate (%)"
];

const ga4PagePerformanceHeaders = [
  "Sr No",
  "Page Location",
  "Current Sessions",
  "Previous Sessions",
  "Sessions Difference",
  "Sessions Change (%)",
  "Current Total Users",
  "Previous Total Users",
  "Current New Users",
  "Previous New Users",
  "Current Page Views",
  "Previous Page Views",
  "Current Engagement Rate (%)",
  "Previous Engagement Rate (%)",
  "Engagement Difference (pp)",
  "Performance Status",
  "Observation"
];

const gscQueryHeaders = [
  "Sr No",
  "Search Query",
  "Clicks",
  "Impressions",
  "CTR (%)",
  "Average Position"
];

const gscPageHeaders = [
  "Sr No",
  "Page URL",
  "Clicks",
  "Impressions",
  "CTR (%)",
  "Average Position"
];

const ga4SummaryItems = cleanRows(ga4SummaryItemsRaw, ga4SummaryHeaders);
const ga4PagePerformanceItems = cleanRows(ga4PagePerformanceItemsRaw, ga4PagePerformanceHeaders);
const gscQueryItems = cleanRows(gscQueryItemsRaw, gscQueryHeaders);
const gscPageItems = cleanRows(gscPageItemsRaw, gscPageHeaders);

function escapeXml(value) {
  if (value === null || value === undefined) return "";
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function columnLetter(colIndex) {
  let letter = "";
  let temp = colIndex + 1;

  while (temp > 0) {
    const remainder = (temp - 1) % 26;
    letter = String.fromCharCode(65 + remainder) + letter;
    temp = Math.floor((temp - 1) / 26);
  }

  return letter;
}

function createSheetXml(rows, headers) {
  const allRows = [
    headers,
    ...rows.map(row => headers.map(header => row[header] !== undefined ? row[header] : ""))
  ];

  let sheetData = "";

  allRows.forEach((row, rowIndex) => {
    const excelRow = rowIndex + 1;
    sheetData += `<row r="${excelRow}">`;

    row.forEach((value, colIndex) => {
      const cellRef = `${columnLetter(colIndex)}${excelRow}`;

      if (typeof value === "number" && !isNaN(value)) {
        sheetData += `<c r="${cellRef}"><v>${value}</v></c>`;
      } else {
        sheetData += `<c r="${cellRef}" t="inlineStr"><is><t>${escapeXml(value)}</t></is></c>`;
      }
    });

    sheetData += `</row>`;
  });

  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
  <sheetData>${sheetData}</sheetData>
</worksheet>`;
}

function crc32(buffer) {
  let table = crc32.table;

  if (!table) {
    table = [];

    for (let i = 0; i < 256; i++) {
      let c = i;

      for (let k = 0; k < 8; k++) {
        c = ((c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1));
      }

      table[i] = c >>> 0;
    }

    crc32.table = table;
  }

  let crc = 0 ^ -1;

  for (let i = 0; i < buffer.length; i++) {
    crc = (crc >>> 8) ^ table[(crc ^ buffer[i]) & 0xff];
  }

  return (crc ^ -1) >>> 0;
}

function dosDateTime(date = new Date()) {
  const dosTime =
    (date.getHours() << 11) |
    (date.getMinutes() << 5) |
    Math.floor(date.getSeconds() / 2);

  const dosDate =
    ((date.getFullYear() - 1980) << 9) |
    ((date.getMonth() + 1) << 5) |
    date.getDate();

  return { dosTime, dosDate };
}

function createZip(files) {
  const localParts = [];
  const centralParts = [];
  let offset = 0;
  const { dosTime, dosDate } = dosDateTime();

  for (const file of files) {
    const nameBuffer = Buffer.from(file.name, "utf8");
    const dataBuffer = Buffer.from(file.content, "utf8");
    const crc = crc32(dataBuffer);

    const localHeader = Buffer.alloc(30);
    localHeader.writeUInt32LE(0x04034b50, 0);
    localHeader.writeUInt16LE(20, 4);
    localHeader.writeUInt16LE(0x0800, 6);
    localHeader.writeUInt16LE(0, 8);
    localHeader.writeUInt16LE(dosTime, 10);
    localHeader.writeUInt16LE(dosDate, 12);
    localHeader.writeUInt32LE(crc, 14);
    localHeader.writeUInt32LE(dataBuffer.length, 18);
    localHeader.writeUInt32LE(dataBuffer.length, 22);
    localHeader.writeUInt16LE(nameBuffer.length, 26);
    localHeader.writeUInt16LE(0, 28);

    localParts.push(localHeader, nameBuffer, dataBuffer);

    const centralHeader = Buffer.alloc(46);
    centralHeader.writeUInt32LE(0x02014b50, 0);
    centralHeader.writeUInt16LE(20, 4);
    centralHeader.writeUInt16LE(20, 6);
    centralHeader.writeUInt16LE(0x0800, 8);
    centralHeader.writeUInt16LE(0, 10);
    centralHeader.writeUInt16LE(dosTime, 12);
    centralHeader.writeUInt16LE(dosDate, 14);
    centralHeader.writeUInt32LE(crc, 16);
    centralHeader.writeUInt32LE(dataBuffer.length, 20);
    centralHeader.writeUInt32LE(dataBuffer.length, 24);
    centralHeader.writeUInt16LE(nameBuffer.length, 28);
    centralHeader.writeUInt16LE(0, 30);
    centralHeader.writeUInt16LE(0, 32);
    centralHeader.writeUInt16LE(0, 34);
    centralHeader.writeUInt16LE(0, 36);
    centralHeader.writeUInt32LE(0, 38);
    centralHeader.writeUInt32LE(offset, 42);

    centralParts.push(centralHeader, nameBuffer);

    offset += localHeader.length + nameBuffer.length + dataBuffer.length;
  }

  const centralDirectory = Buffer.concat(centralParts);
  const localData = Buffer.concat(localParts);

  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(0, 4);
  end.writeUInt16LE(0, 6);
  end.writeUInt16LE(files.length, 8);
  end.writeUInt16LE(files.length, 10);
  end.writeUInt32LE(centralDirectory.length, 12);
  end.writeUInt32LE(localData.length, 16);
  end.writeUInt16LE(0, 20);

  return Buffer.concat([localData, centralDirectory, end]);
}

const files = [
  {
    name: "[Content_Types].xml",
    content: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
  <Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
  <Override PartName="/xl/worksheets/sheet2.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
  <Override PartName="/xl/worksheets/sheet3.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
  <Override PartName="/xl/worksheets/sheet4.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>
