xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <sheets>
    <sheet name="GA4 Summary" sheetId="1" r:id="rId1"/>
    <sheet name="GA4 Page Performance" sheetId="2" r:id="rId2"/>
    <sheet name="GSC Queries" sheetId="3" r:id="rId3"/>
    <sheet name="GSC Pages" sheetId="4" r:id="rId4"/>
  </sheets>
</workbook>`
  },
  {
    name: "xl/_rels/workbook.xml.rels",
    content: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>
  <Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet2.xml"/>
  <Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet3.xml"/>
  <Relationship Id="rId4" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet4.xml"/>
</Relationships>`
  },
  {
    name: "xl/worksheets/sheet1.xml",
    content: createSheetXml(ga4SummaryItems, ga4SummaryHeaders)
  },
  {
    name: "xl/worksheets/sheet2.xml",
    content: createSheetXml(ga4PagePerformanceItems, ga4PagePerformanceHeaders)
  },
  {
    name: "xl/worksheets/sheet3.xml",
    content: createSheetXml(gscQueryItems, gscQueryHeaders)
  },
  {
    name: "xl/worksheets/sheet4.xml",
    content: createSheetXml(gscPageItems, gscPageHeaders)
  }
];

const xlsxBuffer = createZip(files);

return [
  {
    json: {
      fileName,
      ga4SummaryRows: ga4SummaryItems.length,
      ga4PagePerformanceRows: ga4PagePerformanceItems.length,
      gscQueryRows: gscQueryItems.length,
      gscPageRows: gscPageItems.length
    },
    binary: {
      data: {
        data: xlsxBuffer.toString("base64"),
        fileName,
        mimeType: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
      }
    }
  }
];

const rows = $input.first().json.rows || [];

if (rows.length === 0) {
  return [{
    json: {
      "Sr No": "",
      "Page URL": "No Data Available",
      "Clicks": "",
      "Impressions": "",
      "CTR (%)": "",
      "Average Position": ""
    }
  }];
}

return rows.map((row, index) => ({
  json: {
    "Sr No": index + 1,
    "Page URL": row.keys[0],
    "Clicks": row.clicks,
    "Impressions": row.impressions,
    "CTR (%)": Number((row.ctr * 100).toFixed(2)),
    "Average Position": Number(row.position.toFixed(2))
  }
}));

const items = $input.all();

const validFiles = items.filter(item => {
  return item.binary && item.binary.data && item.binary.data.data;
});

if (validFiles.length === 0) {
  throw new Error("No Excel file found in input. Check Create Combined Excel File output.");
}

return [validFiles[validFiles.length - 1]];

const currentItems = $items("Get GA4 Page Current Data").map(item => item.json);
const previousItems = $items("Get GA4 Page Previous Data").map(item => item.json);

function getPage(j) {
  return (
    j.pageLocation ||
    j.landingPagePlusQueryString ||
    j.landingPage ||
    j.pagePathPlusQueryString ||
    j.pagePath ||
    j.pageTitle ||
    "(not set)"
  );
}

function num(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

function engagementPercent(value) {
  const n = num(value);
  if (n <= 1) {
    return n * 100;
  }
  return n;
}

function aggregate(items) {
  const map = {};

  for (const item of items) {
    const page = getPage(item);

    if (!map[page]) {
      map[page] = {
        page,
        sessions: 0,
        totalUsers: 0,
        newUsers: 0,
        screenPageViews: 0,
        engagementWeightedTotal: 0
      };
    }

    const sessions = num(item.sessions);
    const engagementRate = engagementPercent(item.engagementRate);

    map[page].sessions += sessions;
    map[page].totalUsers += num(item.totalUsers);
    map[page].newUsers += num(item.newUsers);
    map[page].screenPageViews += num(item.screenPageViews);
    map[page].engagementWeightedTotal += engagementRate * sessions;
  }

  for (const page of Object.keys(map)) {
    const row = map[page];
    row.engagementRate =
      row.sessions > 0 ? row.engagementWeightedTotal / row.sessions : 0;
  }

  return map;
}

function percentChange(current, previous) {
  if (previous === 0 && current > 0) return "New";
  if (previous === 0 && current === 0) return 0;
  return Number((((current - previous) / previous) * 100).toFixed(2));
}

function getStatus(currentSessions, previousSessions, sessionsChangePercent, engagementDiff) {
  if (previousSessions === 0 && currentSessions > 0) {
    return "New Traffic";
  }

  if (currentSessions === 0 && previousSessions > 0) {
    return "Lost Traffic";
  }

  if (typeof sessionsChangePercent === "number" && sessionsChangePercent >= 20 && engagementDiff >= -5) {
    return "Performing Well";
  }

  if (typeof sessionsChangePercent === "number" && sessionsChangePercent <= -20) {
    return "Needs Attention";
  }

  if (engagementDiff <= -10) {
    return "Engagement Dropped";
  }

  return "Stable";
}

function getObservation(status, sessionsChangePercent, engagementDiff) {
  if (status === "New Traffic") {
    return "This page started receiving traffic in the current period.";
  }

  if (status === "Lost Traffic") {
    return "This page received traffic earlier but has no sessions in the current period.";
  }

  if (status === "Performing Well") {
    return `This page improved by ${sessionsChangePercent}% in sessions compared to the previous period.`;
  }

  if (status === "Needs Attention") {
    return `This page dropped by ${Math.abs(sessionsChangePercent)}% in sessions compared to the previous period.`;
  }

  if (status === "Engagement Dropped") {
    return `Engagement rate dropped by ${Math.abs(engagementDiff).toFixed(2)} percentage points.`;
  }

  return "No major change compared to the previous period.";
}

const currentMap = aggregate(currentItems);
const previousMap = aggregate(previousItems);

const allPages = Array.from(new Set([
  ...Object.keys(currentMap),
  ...Object.keys(previousMap)
]));

if (allPages.length === 0) {
  return [
    {
      json: {
        "Sr No": "",
        "Page Location": "No Data Available",
        "Current Sessions": "",
        "Previous Sessions": "",
        "Sessions Difference": "",
        "Sessions Change (%)": "",
        "Current Total Users": "",
        "Previous Total Users": "",
        "Current New Users": "",
        "Previous New Users": "",
        "Current Page Views": "",
        "Previous Page Views": "",
        "Current Engagement Rate (%)": "",
        "Previous Engagement Rate (%)": "",
        "Engagement Difference (pp)": "",
        "Performance Status": "",
        "Observation": ""
      }
    }
  ];
}

const rows = allPages.map(page => {
  const current = currentMap[page] || {
    sessions: 0,
    totalUsers: 0,
    newUsers: 0,
    screenPageViews: 0,
    engagementRate: 0
  };

  const previous = previousMap[page] || {
    sessions: 0,
    totalUsers: 0,
    newUsers: 0,
    screenPageViews: 0,
    engagementRate: 0
  };

  const sessionsDifference = current.sessions - previous.sessions;
  const sessionsChangePercent = percentChange(current.sessions, previous.sessions);
  const engagementDifference = Number((current.engagementRate - previous.engagementRate).toFixed(2));

  const status = getStatus(
    current.sessions,
    previous.sessions,
    sessionsChangePercent,
    engagementDifference
  );

  return {
    page,
    current,
    previous,
    sessionsDifference,
    sessionsChangePercent,
    engagementDifference,
    status,
    observation: getObservation(status, sessionsChangePercent, engagementDifference)
  };
});

rows.sort((a, b) => b.current.sessions - a.current.sessions);

return rows.slice(0, 50).map((row, index) => {
  return {
    json: {
      "Sr No": index + 1,
      "Page Location": row.page,
      "Current Sessions": row.current.sessions,
      "Previous Sessions": row.previous.sessions,
      "Sessions Difference": row.sessionsDifference,
      "Sessions Change (%)": row.sessionsChangePercent,
      "Current Total Users": row.current.totalUsers,
      "Previous Total Users": row.previous.totalUsers,
      "Current New Users": row.current.newUsers,
      "Previous New Users": row.previous.newUsers,
      "Current Page Views": row.current.screenPageViews,
      "Previous Page Views": row.previous.screenPageViews,
      "Current Engagement Rate (%)": Number(row.current.engagementRate.toFixed(2)),
      "Previous Engagement Rate (%)": Number(row.previous.engagementRate.toFixed(2)),
      "Engagement Difference (pp)": row.engagementDifference,
      "Performance Status": row.status,
      "Observation": row.observation
    }
  };
});

const items = $input.all();

const fileItem = items.find(item => item.binary && item.binary.data);

if (!fileItem) {
  throw new Error("Excel file not found. Check Keep Only One Final Report output.");
}

function extractAiHtml(json) {
  if (!json) return "";

  if (
    Array.isArray(json.output) &&
    json.output[0] &&
    Array.isArray(json.output[0].content) &&
    json.output[0].content[0] &&
    typeof json.output[0].content[0].text === "string"
  ) {
    return json.output[0].content[0].text;
  }

  if (typeof json.text === "string") return json.text;
  if (typeof json.output_text === "string") return json.output_text;
  if (typeof json.response === "string") return json.response;
  if (typeof json.message === "string") return json.message;
  if (typeof json.content === "string") return json.content;

  return "";
}

const aiItem = items.find(item => extractAiHtml(item.json));

const aiSummaryHtml = aiItem
  ? extractAiHtml(aiItem.json)
  : "<p>AI executive summary was not found. Please check Message a model output.</p>";

return [
  {
    json: {
      fileName: fileItem.json.fileName || "Weekly_SEO_GA4_Report.xlsx",
      aiSummaryHtml: aiSummaryHtml
    },
    binary: fileItem.binary
  }
];
